const A=[],AT=[];
const mc=(d,s,t,q,ok,wr,e)=>A.push({s,t,q,o:[ok,...wr],a:0,e,d});
const tf=(d,s,q,v,e)=>A.push({s,t:"True or false",q,o:v?["True","False"]:["False","True"],a:0,e,tf:true,d});
const ty=(d,s,q,a,e,n)=>AT.push(n?{s,q,a,e,n,d}:{s,q,a,e,d});
// ---- S1
mc(2,1,"Case","A student fails an exam and blames only their own laziness, until they learn that most of their class failed because of a badly designed course. Which idea does this illustrate?","Turning a personal trouble into a public issue",["Latent function","Cultural lag","Social closure"],"Mills: many personal troubles can only be understood as public issues, through the link between biography, history and social structure.");
mc(3,1,"Case","A researcher wants to know WHY teenagers quit a social network and runs 20 in-depth interviews. Which approach is this, and what does it capture?","Qualitative: the meanings behind behaviour",["Quantitative: the generalisable patterns of behaviour","Quantitative: the meanings behind behaviour","Qualitative: the statistical frequency of the behaviour"],"Qualitative methods (interviews, focus groups) assess the WHY; quantitative methods (statistics, surveys) find the WHAT.");
mc(2,1,"Perspectives","Which pairing of theory and metaphor is correct?","Functionalism – society as an organism",["Conflict theory – society as a river","Postmodernity – society as an organism","Symbolic interactionism – society as a body whose parts keep balance"],"Functionalism = organism; postmodernity = river; action theories (interactionism) = construction through interaction.");
mc(3,1,"Case","A city builds a speed camera to reduce accidents; as an unintended and unnoticed effect, local shops lose customers because drivers no longer stop. Using Merton, the loss of customers is…","A latent dysfunction",["A manifest function","A latent function","A manifest dysfunction"],"Manifest = intended and recognised; latent = unintended and unrecognised. The harm to shops is an unintended, unrecognised negative effect.");
mc(3,1,"Case","“I stay in this job because my employer pays the best salary for my skills.” Which type of social action in Weber's typology does this reflect?","Instrumental rationality",["Value rationality","Affectual action","Traditional action"],"Instrumental rationality: choosing the most effective means to achieve one's goal.");
mc(3,1,"Case","A woman refuses to work for an arms company, even though the salary is high, because it contradicts her principles. This is…","Value rationality",["Instrumental rationality","Affectual action","Traditional action"],"Value rationality asks “what should I do according to my principles?” whatever the cost.");
mc(2,1,"Case","A family eats the same dish every Christmas Eve “because we have always done so”. In Weber's terms, this is…","Traditional action",["Instrumental rationality","Value rationality","Affectual action"],"Traditional action is guided by habit and custom.");
mc(2,1,"Levels","A study of how two colleagues negotiate a deadline in a meeting is mainly at the…","Micro level",["Macro level","Global level","Structural level"],"Micro = small groups and individuals; macro = large-scale social structures.");
tf(2,1,"For Comte, social statics studies how society changes.",false,"Social statics = how society is held together; social dynamics = how it changes.");
tf(2,1,"Ibn Khaldun's “asabiyyah” refers to the group spirit that makes dynasties and power possible.",true,"Muqaddimah (14th century).");
tf(3,1,"Both functionalism and conflict theory stress that social structures condition individuals.",true,"They differ on whether structure produces harmony (functionalism) or struggle (conflict theory).");
ty(2,1,"Weber's type of action that asks “What do my emotions lead me to do?”",["affectual action","affectual"],"Affectual action is driven by emotions.");
ty(3,1,"Merton's term for an unintended and unrecognised consequence of a social structure",["latent function","latent"],"Manifest = intended and recognised; latent = not.");
