tf(2,4,"Weber saw stratification as based on class, status and power.",true,"A multidimensional view, unlike Marx's focus on ownership.");
tf(3,4,"For Marx, class is mainly defined by prestige and lifestyle.",false,"For Marx class is defined by ownership: capital vs labour.");
ty(2,4,"Bourdieu's term for ingrained, unconscious dispositions and tastes",["habitus"],"Shaped by class and upbringing.");
